"from fastapi import APIRouter, Depends, HTTPException, status\nfrom app.services.auth_service import AuthService\nfrom app.schemas import RegisterRequest, LoginRequest, TokenResponse\n\nrouter = APIRouter(prefix='/auth', tags=['auth'])\n\n@router.post('/register', response_model=TokenResponse)\ndef register(request: RegisterRequest, service: AuthService = Depends()):\n    return service.register(request)\n\n@router.post('/login', response_model=TokenResponse)\ndef login(request: LoginRequest, service: AuthService = Depends()):\n    return service.login(request)\n\n@router.get('/me', response_model=dict)\ndef me(current_user=Depends(service.get_current_user)):\n    return {\"id\": str(current_user.id), \"email\": current_user.email, \"role\": current_user.role}\n"
